<?php use App\Models\{EquipmentModel,Make}; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component; new #[Title('Model')] class extends Component { public ?EquipmentModel $model=null; public ?int $make_id=null; public string $name=''; public function mount(?EquipmentModel $model=null):void{$this->model=$model;if($model){$this->make_id=$model->make_id;$this->name=$model->name;}} public function save():mixed{$d=$this->validate(['make_id'=>['required','exists:makes,id'],'name'=>['required','max:255',Rule::unique('models','name')->where('make_id',$this->make_id)->ignore($this->model?->id)]]);$this->model?->update($d)??EquipmentModel::create($d);return $this->redirectRoute('setup.models.index',navigate:true);}public function with():array{return['makes'=>Make::orderBy('name')->get()];}}; ?>
<section class="w-full p-6"><flux:heading size="xl">{{ $model?'Update':'Create' }} model</flux:heading><form wire:submit="save" class="mt-6 max-w-xl space-y-4"><flux:select wire:model="make_id" label="Make">@foreach($makes as $make)<flux:select.option :value="$make->id">{{$make->name}}</flux:select.option>@endforeach</flux:select><flux:input wire:model="name" label="Model" required/><div class="flex justify-end gap-2"><flux:button :href="route('setup.models.index')" variant="ghost">Cancel</flux:button><flux:button type="submit" variant="primary">Save</flux:button></div></form></section>
